<?php
declare(strict_types=1);
$tables=[];
try{$q=$db->query("SELECT TABLE_NAME, TABLE_ROWS, ROUND((DATA_LENGTH+INDEX_LENGTH)/1024/1024,2) size_mb FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME");$tables=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}
?>
<div class="av4-card" style="padding:15px"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h2 style="margin:0;font-size:15px">🗄️ Database Explorer</h2><p style="margin:3px 0 0;color:#7e8898;font-size:9px">Read-only overview of the current database schema.</p></div><a class="av4-link" href="/smart-toolz/admin/db-browser.php">Open Full DB Explorer ↗</a></div><div style="margin-top:12px;overflow:auto"><table style="width:100%;border-collapse:collapse;font-size:10px"><thead><tr><th style="text-align:left;padding:8px;background:#fafbfe">Table</th><th style="text-align:right;padding:8px;background:#fafbfe">Rows</th><th style="text-align:right;padding:8px;background:#fafbfe">Size MB</th></tr></thead><tbody><?php foreach($tables as $r):?><tr><td style="padding:8px;border-bottom:1px solid #edf0f4"><?=av4h($r['TABLE_NAME'])?></td><td style="padding:8px;border-bottom:1px solid #edf0f4;text-align:right"><?=number_format((int)$r['TABLE_ROWS'])?></td><td style="padding:8px;border-bottom:1px solid #edf0f4;text-align:right"><?=av4h($r['size_mb'])?></td></tr><?php endforeach; if(!$tables):?><tr><td colspan="3" style="padding:15px;text-align:center;color:#8993a4">Could not read database tables.</td></tr><?php endif;?></tbody></table></div></div>
